function getCategoryForEntityType(type, metadata) {
  switch (type) {
    case "person":
      return "people";
    case "email_thread":
      return "email";
    case "topic":
      return "knowledge";
    case "document": {
      const source = metadata?.source;
      if (source === "email")
        return "email";
      if (source === "calendar")
        return "calendar";
      if (source === "contact")
        return "people";
      if (source === "messaging")
        return "social";
      if (source === "social")
        return "social";
      if (source === "financial")
        return "finance";
      if (source === "health")
        return "health";
      if (source === "browser_history")
        return "browser";
      if (source === "cloud_storage")
        return "cloud";
      if (source === "photos_metadata")
        return "cloud";
      if (source === "local_file")
        return "knowledge";
      if (source === "note")
        return "knowledge";
      if (source) {
        const connectorCat = CONNECTOR_TO_CATEGORY[source];
        if (connectorCat)
          return connectorCat;
      }
      return "knowledge";
    }
    case "directory":
      return "knowledge";
    case "event":
      return "calendar";
    case "reminder":
      return "calendar";
    case "location":
      return "people";
    case "category":
      return "knowledge";
    default:
      return "knowledge";
  }
}
function getAllCategories() {
  return [
    "email",
    "calendar",
    "health",
    "finance",
    "social",
    "work",
    "reading",
    "music",
    "cloud",
    "browser",
    "people",
    "knowledge"
  ];
}

