var LEGAL_PATTERNS = [
  /\bcontract\b/i,
  /\bagreement\b/i,
  /\bbinding\b/i,
  /\bterms and conditions\b/i,
  /\bnon-disclosure\b/i,
  /\bNDA\b/,
  /\bliability\b/i,
  /\bindemnif/i,
  /\barbitration\b/i,
  /\bjurisdiction\b/i,
  /\bwaiver\b/i,
  /\bpower of attorney\b/i
];
var IRREVERSIBLE_ACTIONS = [
  "calendar.delete",
  "connector.disconnect"
  // Re-auth requires user interaction with third-party OAuth
];
var DEFAULT_CONFIG = {
  financialThreshold: 500,
  confidenceThreshold: 0.7
};
var BoundaryEnforcer = class {
  db;
  config;
  constructor(db, config) {
    this.db = db;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }
  /**
   * Check all boundaries for a given action. Returns triggered boundaries.
   */
  checkBoundaries(input) {
    const boundaries = [];
    const financial = this.checkFinancial(input.payload);
    if (financial)
      boundaries.push(financial);
    const legal = this.checkLegal(input.payload);
    if (legal)
      boundaries.push(legal);
    const irreversible = this.checkIrreversible(input.action);
    if (irreversible)
      boundaries.push(irreversible);
    const novel = this.checkNovel(input.action);
    if (novel)
      boundaries.push(novel);
    if (input.llmConfidence !== void 0) {
      const lowConf = this.checkConfidence(input.llmConfidence);
      if (lowConf)
        boundaries.push(lowConf);
    }
    return boundaries;
  }
  /**
   * Returns true if any boundary was triggered — action should escalate.
   */
  shouldEscalate(boundaries) {
    return boundaries.length > 0;
  }
  // ─── Individual Checks ──────────────────────────────────────────────────
  checkFinancial(payload) {
    const amount = payload["amount"];
    if (amount !== void 0 && amount > this.config.financialThreshold) {
      return {
        type: "financial_threshold",
        reason: `Amount $${amount} exceeds threshold $${this.config.financialThreshold}`,
        severity: "high"
      };
    }
    return null;
  }
  checkLegal(payload) {
    const textFields = ["body", "subject", "description", "text", "content"];
    for (const field of textFields) {
      const value = payload[field];
      if (typeof value === "string") {
        for (const pattern of LEGAL_PATTERNS) {
          if (pattern.test(value)) {
            return {
              type: "legal_language",
              reason: `Legal language detected: "${value.slice(0, 80)}..."`,
              severity: "high"
            };
          }
        }
      }
    }
    return null;
  }
  checkIrreversible(action) {
    if (IRREVERSIBLE_ACTIONS.includes(action)) {
      return {
        type: "irreversible",
        reason: `Action '${action}' is irreversible`,
        severity: "high"
      };
    }
    return null;
  }
  checkNovel(action) {
    const readActions = [
      "web.search",
      "web.deep_search",
      "web.fetch",
      "email.fetch",
      "calendar.fetch",
      "reminder.list",
      "contacts.list",
      "contacts.get",
      "contacts.search",
      "contacts.import",
      "finance.fetch_transactions",
      "health.fetch",
      "finance.plaid_sync",
      "finance.plaid_balances",
      "finance.plaid_status",
      "messaging.read",
      "clipboard.analyze"
    ];
    if (readActions.includes(action))
      return null;
    try {
      const row = this.db.prepare("SELECT COUNT(*) as count FROM approval_patterns WHERE action_type = ?").get(action);
      if (!row || row.count === 0) {
        return {
          type: "novel",
          reason: `No prior approvals for action '${action}'`,
          severity: "medium"
        };
      }
    } catch {
      return {
        type: "novel",
        reason: `No prior approvals for action '${action}'`,
        severity: "medium"
      };
    }
    return null;
  }
  checkConfidence(confidence) {
    if (confidence < this.config.confidenceThreshold) {
      return {
        type: "low_confidence",
        reason: `LLM confidence ${(confidence * 100).toFixed(0)}% below threshold ${(this.config.confidenceThreshold * 100).toFixed(0)}%`,
        severity: "medium"
      };
    }
    return null;
  }
};

